/**
 * TodoMVC App - Vanilla JavaScript implementation.
 */
(function () {
  'use strict';

  // --- Storage ---
  var STORAGE_KEY = 'todos-shakedown';
  var FILTER_KEY = 'todos-shakedown-filter';

  /**
   * Load todos from localStorage.
   * @planks("the page is reloaded")
   */
  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  /**
   * Persist todos to localStorage.
   * @planks("the user types {string} in the new-todo input and presses Enter")
   * @planks("the user toggles the checkbox for todo {string}")
   * @planks("the user toggles the toggle-all checkbox on")
   * @planks("the user clears the edit input and types {string} and presses Enter")
   * @planks("the user clears the edit input and types {string} and triggers blur")
   * @planks("the user clears the edit input and presses Enter")
   * @planks("the user clicks the destroy button for todo {string}")
   * @planks("the user clicks the Clear completed button")
   */
  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // --- State ---
  var todos = loadTodos();
  var currentFilter = loadFilter();

  /**
   * Derive filter from URL hash.
   * @planks("the user navigates to the {string} filter")
   */
  function getFilterFromHash() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  /**
   * Load filter from localStorage or hash.
   * @planks("the user navigates to the {string} filter")
   */
  function loadFilter() {
    var stored = localStorage.getItem(FILTER_KEY);
    if (stored === 'active' || stored === 'completed' || stored === 'all') return stored;
    return getFilterFromHash();
  }

  /**
   * Persist filter to localStorage.
   * @planks("the user navigates to the {string} filter")
   */
  function saveFilter(filter) {
    localStorage.setItem(FILTER_KEY, filter);
  }

  // --- DOM refs ---
  /** @planks-provisional("features/counter-behaviour.feature:Counter displays remaining items with correct pluralisation") */
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  // --- Render ---
  /**
   * Render the full application state to the DOM.
   * @planks("the app is loaded in the browser")
   */
  function render() {
    var filtered = todos.filter(function (todo) {
      if (currentFilter === 'active') return !todo.completed;
      if (currentFilter === 'completed') return todo.completed;
      return true;
    });

    // Clear list
    todoList.innerHTML = '';

    // Build items
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.setAttribute('data-id', todo.id);
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    // Main section visibility
    var hasTodos = todos.length > 0;
    mainSection.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Toggle all state
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAllCheckbox.checked = allCompleted;

    // Counter
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var pluralized = activeCount === 1 ? 'item left' : 'items left';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralized;

    // Clear completed visibility
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? 'block' : 'none';

    // Filter selection
    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
    });
    var filterHash = currentFilter === 'active' ? '#/active' : currentFilter === 'completed' ? '#/completed' : '#/';
    filterLinks.forEach(function (link) {
      if (link.getAttribute('href') === filterHash) {
        link.classList.add('selected');
      }
    });
  }

  /**
   * Escape HTML entities to prevent XSS.
   * @planks-provisional("features/counter-behaviour.feature:Counter displays remaining items with correct pluralisation")
   */
  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  // --- Helpers ---
  /**
   * Generate a unique todo ID.
   * @planks("the user types {string} in the new-todo input and presses Enter")
   */
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
  }

  /**
   * Find a todo by its ID.
   * @planks("the user toggles the checkbox for todo {string}")
   * @planks("the user double-clicks the label for todo {string}")
   * @planks("the user clears the edit input and types {string} and presses Enter")
   * @planks("the user clears the edit input and types {string} and triggers blur")
   * @planks("the user clears the edit input and presses Enter")
   * @planks("the user clears the edit input and types {string} and presses Escape")
   * @planks("the user clicks the destroy button for todo {string}")
   */
  function findTodoById(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return todos[i];
    }
    return null;
  }

  /**
   * Find a todo index by its ID.
   * @planks-provisional("features/counter-behaviour.feature:Counter displays remaining items with correct pluralisation")
   */
  function findTodoIndexById(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) return i;
    }
    return -1;
  }

  // --- Event handlers ---

  // New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      addTodo();
    }
  });

  /**
   * Create a new todo from the input value.
   * @planks("the user types {string} in the new-todo input and presses Enter")
   */
  function addTodo() {
    var title = newTodoInput.value.trim();
    if (!title) {
      newTodoInput.value = '';
      return;
    }
    todos.push({ id: generateId(), title: title, completed: false });
    saveTodos(todos);
    newTodoInput.value = '';
    render();
  }

  // Toggle all
  /** @planks("the user toggles the toggle-all checkbox on") */
  toggleAllCheckbox.addEventListener('change', function () {
    var checked = toggleAllCheckbox.checked;
    todos.forEach(function (todo) {
      todo.completed = checked;
    });
    saveTodos(todos);
    render();
  });

  // Todo list events (delegated)
  todoList.addEventListener('change', function (e) {
    if (e.target.classList.contains('toggle')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      var todo = findTodoById(id);
      if (todo) {
        todo.completed = e.target.checked;
        saveTodos(todos);
        render();
      }
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.value = e.target.textContent;
      editInput.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');

      if (e.key === 'Enter' || e.keyCode === 13) {
        saveEdit(li, id, e.target.value);
      } else if (e.key === 'Escape' || e.keyCode === 27) {
        li.classList.remove('editing');
        e.target.value = findTodoById(id).title;
      }
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      saveEdit(li, id, e.target.value);
    }
  }, true);

  /**
   * Save an edit or delete if empty.
   * @planks("the user clears the edit input and types {string} and presses Enter")
   * @planks("the user clears the edit input and types {string} and triggers blur")
   * @planks("the user clears the edit input and presses Enter")
   */
  function saveEdit(li, id, value) {
    var trimmed = value.trim();
    if (!trimmed) {
      // Delete todo if edit is empty
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      var todo = findTodoById(id);
      if (todo) todo.title = trimmed;
    }
    li.classList.remove('editing');
    saveTodos(todos);
    render();
  }

  todoList.addEventListener('click', function (e) {
    /** @planks("the user clicks the destroy button for todo {string}") */
    if (e.target.classList.contains('destroy')) {
      var li = e.target.closest('li');
      var id = li.getAttribute('data-id');
      todos = todos.filter(function (t) { return t.id !== id; });
      saveTodos(todos);
      render();
    }
  });

  // Clear completed
  /** @planks("the user clicks the Clear completed button") */
  clearCompletedBtn.addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  });

  // Routing
  /** @planks("the user navigates to the {string} filter") */
  window.addEventListener('hashchange', function () {
    currentFilter = getFilterFromHash();
    saveFilter(currentFilter);
    render();
  });

  filterLinks.forEach(function (link) {
    /** @planks("the user navigates to the {string} filter") */
    link.addEventListener('click', function (e) {
      e.preventDefault();
      window.location.hash = link.getAttribute('href');
    });
  });

  // --- Initial render ---
  /** @planks("the app is loaded in the browser") */
  render();
})();

const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.dom = null;
    this.document = null;
    this.window = null;
  }

  loadApp() {
    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Remove CSS links that don't exist in test env
    html = html.replace(/<link rel="stylesheet" href="[^"]*todomvc-common\/base\.css">/g, '');
    html = html.replace(/<link rel="stylesheet" href="[^"]*todomvc-app-css\/index\.css">/g, '');
    html = html.replace(/<link rel="stylesheet" href="[^"]*css\/app\.css">/g, '');

    // Remove todomvc-common base.js reference (not needed for tests)
    html = html.replace(/<script src="[^"]*todomvc-common\/base\.js"><\/script>/g, '');

    // Create happy-dom window
    this.window = new Window({
      url: 'file://' + path.resolve(__dirname, '../../') + '/index.html',
    });
    this.document = this.window.document;

    // Set up HTML
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Load the app script
    const appScriptPath = path.resolve(__dirname, '../../js/app.js');
    if (fs.existsSync(appScriptPath)) {
      const appScript = fs.readFileSync(appScriptPath, 'utf8');
      try {
        this.window.eval(appScript);
      } catch (e) {
        console.error('Error loading app.js:', e.message);
      }
    }
  }

  reloadApp() {
    // Save localStorage state
    const localStorageBackup = {};
    if (this.window && this.window.localStorage) {
      for (let i = 0; i < this.window.localStorage.length; i++) {
        const key = this.window.localStorage.key(i);
        localStorageBackup[key] = this.window.localStorage.getItem(key);
      }
    }
    // Create new window first, restore localStorage, then load app
    this.loadApp();
    // Restore localStorage BEFORE app script runs (loadApp already ran eval)
    // So we need to re-run the app after restoring
    if (this.window && this.window.localStorage) {
      Object.entries(localStorageBackup).forEach(([key, value]) => {
        this.window.localStorage.setItem(key, value);
      });
    }
    // Re-run app script to pick up restored localStorage
    const appScriptPath = require('path').resolve(__dirname, '../../js/app.js');
    if (require('fs').existsSync(appScriptPath)) {
      const appScript = require('fs').readFileSync(appScriptPath, 'utf8');
      try {
        this.window.eval(appScript);
      } catch (e) {
        console.error('Error re-running app.js:', e.message);
      }
    }
  }

  // --- Query helpers ---

  get newTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  get todoList() {
    return this.document.querySelector('.todo-list');
  }

  get mainSection() {
    return this.document.querySelector('.main');
  }

  get footer() {
    return this.document.querySelector('.footer');
  }

  get toggleAllCheckbox() {
    return this.document.querySelector('.toggle-all');
  }

  get todoCount() {
    return this.document.querySelector('.todo-count');
  }

  get clearCompletedButton() {
    return this.document.querySelector('.clear-completed');
  }

  get todoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  todoItemAt(index) {
    return this.todoItems[index] || null;
  }

  todoItemByTitle(title) {
    return this.todoItems.find(li => {
      const label = li.querySelector('label');
      return label && label.textContent === title;
    }) || null;
  }

  // --- Action helpers ---

  typeInNewTodo(text) {
    const input = this.newTodoInput;
    input.value = text;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  pressEnterInNewTodo() {
    const input = this.newTodoInput;
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }

  toggleTodoByTitle(title) {
    const item = this.todoItemByTitle(title);
    if (!item) throw new Error(`Todo "${title}" not found`);
    const checkbox = item.querySelector('.toggle');
    checkbox.click();
  }

  toggleAllOn() {
    if (!this.toggleAllCheckbox.checked) {
      this.toggleAllCheckbox.click();
    }
  }

  toggleAllOff() {
    if (this.toggleAllCheckbox.checked) {
      this.toggleAllCheckbox.click();
    }
  }

  doubleClickLabel(title) {
    const item = this.todoItemByTitle(title);
    if (!item) throw new Error(`Todo "${title}" not found`);
    const label = item.querySelector('label');
    const event = new this.window.Event('dblclick', { bubbles: true });
    label.dispatchEvent(event);
  }

  clearEditAndType(text) {
    const editingItem = this.document.querySelector('.todo-list li.editing');
    if (!editingItem) throw new Error('No item in editing mode');
    const editInput = editingItem.querySelector('.edit');
    editInput.value = text;
    editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  pressEnterInEdit() {
    const editingItem = this.document.querySelector('.todo-list li.editing');
    if (!editingItem) throw new Error('No item in editing mode');
    const editInput = editingItem.querySelector('.edit');
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    editInput.dispatchEvent(event);
  }

  pressEscapeInEdit() {
    const editingItem = this.document.querySelector('.todo-list li.editing');
    if (!editingItem) throw new Error('No item in editing mode');
    const editInput = editingItem.querySelector('.edit');
    const event = new this.window.KeyboardEvent('keydown', {
      key: 'Escape',
      keyCode: 27,
      which: 27,
      bubbles: true,
    });
    editInput.dispatchEvent(event);
  }

  blurEdit() {
    const editingItem = this.document.querySelector('.todo-list li.editing');
    if (!editingItem) throw new Error('No item in editing mode');
    const editInput = editingItem.querySelector('.edit');
    editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }

  clickDestroyForTodo(title) {
    const item = this.todoItemByTitle(title);
    if (!item) throw new Error(`Todo "${title}" not found`);
    const destroyBtn = item.querySelector('.destroy');
    destroyBtn.click();
  }

  clickClearCompleted() {
    this.clearCompletedButton.click();
  }

  navigateToFilter(filter) {
    const filterMap = {
      'All': '#/',
      'Active': '#/active',
      'Completed': '#/completed',
    };
    const hash = filterMap[filter];
    if (!hash) throw new Error(`Unknown filter: ${filter}`);
    this.window.location.hash = hash;
    // Trigger hashchange
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  getSelectedFilter() {
    const selected = this.document.querySelector('.filters a.selected');
    if (!selected) return null;
    return selected.textContent;
  }

  createTodo(title, completed = false) {
    this.typeInNewTodo(title);
    this.pressEnterInNewTodo();
    if (completed) {
      this.toggleTodoByTitle(title);
    }
  }

  createTodosWithData(data) {
    data.hashes().forEach(row => {
      this.createTodo(row.title, row.completed === 'true' || row.completed === true);
    });
  }
}

setWorldConstructor(AppWorld);

{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// --- Background ---

Given('the app is loaded in the browser', function () {
  this.loadApp();
});

// --- Empty state ---

Given('the todo list is empty', function () {
  // Remove sample items from template
  this.window.localStorage.clear();
  this.reloadApp();
  // Clear any sample todo items left from the template
  const items = this.document.querySelectorAll('.todo-list li');
  items.forEach(li => li.remove());
  assert.strictEqual(this.todoItems.length, 0, 'Expected todo list to be empty');
});

Then('the main section is hidden', function () {
  const main = this.mainSection;
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'Expected main section to be hidden');
});

Then('the footer is hidden', function () {
  const footer = this.footer;
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Expected footer to be hidden');
});

// --- Creating todos ---

When('the user types {string} in the new-todo input and presses Enter', function (text) {
  this.typeInNewTodo(text);
  this.pressEnterInNewTodo();
});

Then('the todo list contains {int} item(s)', function (count) {
  assert.strictEqual(this.todoItems.length, count, `Expected ${count} items but found ${this.todoItems.length}`);
});

Then('the new-todo input is empty', function () {
  assert.strictEqual(this.newTodoInput.value, '', 'Expected new-todo input to be empty');
});

Then('the todo at index {int} has title {string} and is not completed', function (index, title) {
  const item = this.todoItemAt(index);
  assert.ok(item, `No todo at index ${index}`);
  const label = item.querySelector('label');
  assert.strictEqual(label.textContent, title, `Expected title "${title}" but got "${label.textContent}"`);
  assert.ok(!item.classList.contains('completed'), 'Expected todo to not be completed');
});

// --- Single todo existence ---

Given('a todo {string} exists', function (title) {
  this.createTodo(title, false);
});

Given('a completed todo {string} exists', function (title) {
  this.createTodo(title, true);
});

// --- Multiple todos existence ---

Given('these todos exist:', function (dataTable) {
  this.createTodosWithData(dataTable);
});

// --- Completing todos ---

When('the user toggles the checkbox for todo {string}', function (title) {
  this.toggleTodoByTitle(title);
});

Then('the todo {string} is completed', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(item.classList.contains('completed'), `Expected "${title}" to be completed`);
});

Then('the todo {string} is not completed', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(!item.classList.contains('completed'), `Expected "${title}" to not be completed`);
});

Then('the item count shows {string}', function (expected) {
  const countEl = this.todoCount;
  assert.ok(countEl, 'Todo count element not found');
  const strong = countEl.querySelector('strong');
  const countText = strong.textContent;
  const suffix = countEl.textContent.replace(countText, '').trim();
  const actual = `${countText} ${suffix}`;
  assert.strictEqual(actual, expected, `Expected "${expected}" but got "${actual}"`);
});

// --- Toggle all ---

When('the user toggles the toggle-all checkbox on', function () {
  this.toggleAllOn();
});

Then('all todos are completed', function () {
  this.todoItems.forEach((item, i) => {
    assert.ok(item.classList.contains('completed'), `Todo at index ${i} not completed`);
  });
});

Then('the toggle-all checkbox is unchecked', function () {
  assert.ok(!this.toggleAllCheckbox.checked, 'Expected toggle-all to be unchecked');
});

Then('the toggle-all checkbox is checked', function () {
  assert.ok(this.toggleAllCheckbox.checked, 'Expected toggle-all to be checked');
});

// --- Editing ---

When('the user double-clicks the label for todo {string}', function (title) {
  this.doubleClickLabel(title);
});

Then('the todo {string} is in editing mode', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(item.classList.contains('editing'), `Expected "${title}" to be in editing mode`);
});

When('the user clears the edit input and types {string} and presses Enter', function (text) {
  this.clearEditAndType(text);
  this.pressEnterInEdit();
});

When('the user clears the edit input and types {string} and triggers blur', function (text) {
  this.clearEditAndType(text);
  this.blurEdit();
});

When('the user clears the edit input and presses Enter', function () {
  this.clearEditAndType('');
  this.pressEnterInEdit();
});

When('the user clears the edit input and types {string} and presses Escape', function (text) {
  this.clearEditAndType(text);
  this.pressEscapeInEdit();
});

Then('the todo {string} is not in editing mode', function (title) {
  const item = this.todoItemByTitle(title);
  assert.ok(item, `Todo "${title}" not found`);
  assert.ok(!item.classList.contains('editing'), `Expected "${title}" to not be in editing mode`);
});

// --- Deleting ---

When('the user clicks the destroy button for todo {string}', function (title) {
  this.clickDestroyForTodo(title);
});

// --- Counter ---

Then('the item count shows {int} item(s) left', function (count) {
  const countEl = this.todoCount;
  assert.ok(countEl, 'Todo count element not found');
  const strong = countEl.querySelector('strong');
  assert.strictEqual(parseInt(strong.textContent, 10), count, `Expected count ${count}`);
  const fullText = countEl.textContent.trim();
  if (count === 1) {
    assert.ok(fullText.includes('1 item left'), `Expected "1 item left" but got "${fullText}"`);
  } else {
    assert.ok(fullText.includes(`${count} items left`), `Expected "${count} items left" but got "${fullText}"`);
  }
});

// --- Clear completed ---

When('the user clicks the Clear completed button', function () {
  this.clickClearCompleted();
});

Then('the Clear completed button is hidden', function () {
